using LibreKO.Editors.Contracts;
using LibreKO.Editors.Core;
using LibreKO.Editors.Core.Events;
using LibreKO.Editors.DataHost.Events;
using Microsoft.EntityFrameworkCore;
public class EventHistoryDatabaseTests {
 [Fact] public async Task CreationReversePreservesLaterRows(){await EventFixture.Ensure();var root=Path.Combine(Path.GetTempPath(),"event-history-"+Guid.NewGuid());var service=new EventDatabase(EventFixture.Cs,root);var d=EventFixture.Race(EventFixture.Id());var c=d.BuildChange(Guid.NewGuid());Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(c)).Status);Assert.Single(await service.HistoryAsync());await using(var db=EventFixture.Open()){db.CollectionRaceSchedules.Add(new(){Id=EventFixture.Id(),RaceId=d.Original.Key.Id,Hour=7});await db.SaveChangesAsync();}Assert.Equal(SaveStatus.Conflict,(await service.ReplayAsync(c.OperationId,true)).Status);Assert.Equal(5,(await service.GetAsync(d.Original.Key))!.Rows.Count);var other=new EventDatabase(EventFixture.Cs,Path.Combine(Path.GetTempPath(),"event-history-other-"+Guid.NewGuid()));await Assert.ThrowsAsync<FileNotFoundException>(()=>other.HistoryEntryAsync(c.OperationId));}
 [Fact] public async Task ReverseUpdatePreservesLaterUnrelatedChanges(){await EventFixture.Ensure();var service=new EventDatabase(EventFixture.Cs,Path.Combine(Path.GetTempPath(),"event-history-"+Guid.NewGuid()));var d=EventFixture.Race(EventFixture.Id());Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(d.BuildChange(Guid.NewGuid()))).Status);var edit=new EventDraft((await service.GetAsync(d.Original.Key))!);var key=edit.Rows.Single(r=>r.Key.Table==EventTable.CollectionRaces).Key;edit.Set(key,"Name","Changed name");var c=edit.BuildChange(Guid.NewGuid());Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(c)).Status);await using(var db=EventFixture.Open()){await db.CollectionRaces.Where(r=>r.Id==key.Id).ExecuteUpdateAsync(s=>s.SetProperty(r=>r.MaxWinners,31));}Assert.Equal(SaveStatus.Saved,(await service.ReplayAsync(c.OperationId,true)).Status);var row=(await service.GetAsync(d.Original.Key))!.Rows.Single(r=>r.Key==key);Assert.Equal("31",row.Values["MaxWinners"]!.ToString());Assert.Equal("Test race",row.Values["Name"]!.ToString());Assert.Equal(SaveStatus.Saved,(await service.ReplayAsync(c.OperationId,false)).Status);}
 [Fact] public async Task PostCommitFailureReconcilesWithoutWritingAgain(){await EventFixture.Ensure();var root=Path.Combine(Path.GetTempPath(),"event-recovery-"+Guid.NewGuid());var journal=new EventJournal(root);var service=new EventDatabase(EventFixture.Cs,root,new FailFinalization(journal));var draft=EventFixture.Race(EventFixture.Id());var c=draft.BuildChange(Guid.NewGuid());Assert.Equal(SaveStatus.UnknownCommit,(await service.SaveAsync(c)).Status);Assert.Single(journal.Pending());var normal=new EventDatabase(EventFixture.Cs,root);var before=(await normal.GetAsync(c.Before.Key))!.Version;Assert.Equal(RecoveryDisposition.Applied,await normal.ReconcileAsync(c.OperationId));Assert.Empty(journal.Pending());Assert.Equal(before,(await normal.GetAsync(c.Before.Key))!.Version);Assert.Single(await normal.HistoryAsync());}
 sealed class FailFinalization(EventJournal journal):IEventJournal {public void Prepare(EventChange c)=>journal.Prepare(c);public void Commit(EventChange c,EventDocumentSnapshot? after)=>throw new IOException("fixture finalization");public void Abort(Guid id)=>journal.Abort(id);}
}
